ticket_ids = list_tickets('open')
tickets = [get_ticket(tid) for tid in ticket_ids]
high_priority = [t for t in tickets if t['priority'] == 'high']
gold_customers = set()
for t in high_priority:
    try:
        cust = get_customer(t['customer_id'])
        if cust['tier'] == 'gold':
            gold_customers.add(cust['id'])
    except ToolError:
        continue
results = [send_message(cid, 'We are on it.') for cid in gold_customers]
print(len(results))

