tickets = list_tickets('open')
old_tickets = []
for t in tickets:
    info = get_ticket(t)
    if info['age_days'] > 21:
        old_tickets.append(info['id'])
for t in old_tickets:
    update_ticket(t, 'closed')
print(len(old_tickets))

